import random
random.seed(42)

def irv_eliminate(scores):
    active = dict(scores)
    order = []
    while len(active) > 1:
        loser = min(active, key=lambda k: active[k])
        order.append(loser)
        del active[loser]
    order.append(next(iter(active)))
    return order

def min_gap(scores):
    active = dict(scores)
    gaps = []
    while len(active) > 1:
        sv = sorted(active.items(), key=lambda x: x[1])
        gaps.append(sv[1][1] - sv[0][1])
        del active[sv[0][0]]
    return min(gaps) if gaps else float('inf')

scores = {0: 0.0, 1: 2.0, 2: 3.5, 3: 6.0}
orig_gap = min_gap(scores)
for eps in [0.1, 0.3, 0.5, 0.8]:
    worst = float('inf')
    for _ in range(50000):
        p = {k: v + random.uniform(-eps, eps) for k, v in scores.items()}
        worst = min(worst, min_gap(p))
    bound = orig_gap - 2*eps
    print(f'eps={eps:.1f}: theoretical_lower={bound:.2f}, empirical_worst={worst:.4f}, holds={worst >= bound - 1e-12}')

